'use strict';
// Research-only next-edge lab: Compression Expansion, Liquidity Trap, London->NY handoff.
// 75% DEV selection, final 25% untouched HOLD. One open trade/model. Next M5 open. SL before TP on ambiguous bar.
const fs=require('fs');const raw=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=raw.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,cut=Math.floor(N*.75);
function atr(p=14){let A=Array(N).fill(NaN);for(let i=p;i<N;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));A[i]=s/p}return A}const A=atr();const hr=i=>new Date(M[i].t).getUTCHours();
function run(sig,slA,rr,hold,lo,hi){let T=[],o=null;for(let i=Math.max(80,lo);i<Math.min(N-1,hi);i++){if(o){let b=M[i],px=null;if(o.side==='BUY'){if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp}else{if(b.h>=o.sl)px=o.sl;else if(b.l<=o.tp)px=o.tp}if(px==null&&i-o.ei+1>=hold)px=b.c;if(px!=null){T.push({...o,xi:i,xt:b.t,r:o.side==='BUY'?(px-o.en)/(o.en-o.sl):(o.en-px)/(o.sl-o.en)});o=null}continue}let side=sig(i);if(!side||!Number.isFinite(A[i]))continue;let en=M[i+1].o,r=slA*A[i];o={side,en,sl:side==='BUY'?en-r:en+r,tp:side==='BUY'?en+rr*r:en-rr*r,ei:i+1,et:M[i+1].t}}return T}
function st(T){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,ml=0;for(let x of T){e+=x.r;if(x.r>0){gp+=x.r;w++;ls=0}else{gl+=-x.r;ls++;ml=Math.max(ml,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:T.length,wr:T.length?100*w/T.length:0,pf:gl?gp/gl:gp?Infinity:0,net:e,dd,ls:ml}}
let models=[];function add(fam,cfg,mk){let D=run(mk,.8,cfg.rr,cfg.hold,0,cut),d=st(D);if(d.n<25)return;models.push({fam,cfg,mk,d,score:d.net+Math.min(d.pf,3)*5-d.dd*.6})}
// COMP: prior narrow N-bar box relative ATR; signal closes outside box with controlled body. Deliberately box-based, not Rapid prev3/H1 trend.
for(let n of [6,9,12])for(let width of [.8,1,1.2])for(let body of [.45,.6])for(let rr of [1,1.25,1.5])for(let hold of [8,12]){let cfg={n,width,body,rr,hold};add('COMP',cfg,i=>{if(i<n+20)return;let H=-Infinity,L=Infinity;for(let j=i-n;j<i;j++){H=Math.max(H,M[j].h);L=Math.min(L,M[j].l)}if((H-L)/A[i]>width)return;let b=M[i],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg<body)return;if(b.c>H)return'BUY';if(b.c<L)return'SELL'})}
// TRAP: sweep prior N-bar extreme by ATR amount, then close back inside range; wick/body quality.
for(let n of [6,12,18])for(let sw of [.05,.12,.2])for(let wick of [.45,.6])for(let rr of [1,1.25,1.5])for(let hold of [6,10]){let cfg={n,sw,wick,rr,hold};add('TRAP',cfg,i=>{let H=-Infinity,L=Infinity;for(let j=i-n;j<i;j++){H=Math.max(H,M[j].h);L=Math.min(L,M[j].l)}let b=M[i],rg=b.h-b.l;if(!(rg>0))return;let uw=(b.h-Math.max(b.o,b.c))/rg,lw=(Math.min(b.o,b.c)-b.l)/rg;if(b.h>H+sw*A[i]&&b.c<H&&uw>=wick)return'SELL';if(b.l<L-sw*A[i]&&b.c>L&&lw>=wick)return'BUY'})}
// HANDOFF: London range 07:00-11:59 UTC, entries only 12-16 UTC on rejection/continuation of that day's range.
for(let mode of ['REJECT','CONT'])for(let pad of [.05,.15,.3])for(let body of [.4,.55])for(let rr of [1,1.25,1.5])for(let hold of [8,12]){let cfg={mode,pad,body,rr,hold};add('HANDOFF',cfg,i=>{let h=hr(i);if(h<12||h>16)return;let d=new Date(M[i].t).toISOString().slice(0,10),H=-Infinity,L=Infinity,c=0;for(let j=i-1;j>=0&&c<300;j--,c++){if(new Date(M[j].t).toISOString().slice(0,10)!==d)break;let x=hr(j);if(x>=7&&x<12){H=Math.max(H,M[j].h);L=Math.min(L,M[j].l)}}if(!Number.isFinite(H))return;let b=M[i],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg<body)return;if(mode==='REJECT'){if(b.h>H+pad*A[i]&&b.c<H)return'SELL';if(b.l<L-pad*A[i]&&b.c>L)return'BUY'}else{if(b.c>H+pad*A[i])return'BUY';if(b.c<L-pad*A[i])return'SELL'}})}
models.sort((a,b)=>b.score-a.score);console.log(`NEXT EDGE LAB | M5=${N} | DEV=${cut} HOLD=${N-cut}`);for(let fam of ['COMP','TRAP','HANDOFF']){console.log(`\n🏆 ${fam} TOP DEV + UNTOUCHED HOLD`);let top=models.filter(x=>x.fam===fam).slice(0,12);top.forEach((x,z)=>{let H=st(run(x.mk,.8,x.cfg.rr,x.cfg.hold,cut,N));console.log(`${z+1} ${JSON.stringify(x.cfg)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${H.n} WR${H.wr.toFixed(1)} PF${H.pf.toFixed(2)} N${H.net>=0?'+':''}${H.net.toFixed(2)} DD${H.dd.toFixed(2)}`)})}
console.log('\nRULE: do not promote from DEV. Candidate must survive HOLD with positive net/PF, enough trades, then exact 8-strategy collision/DD integration.');